import {
  DEFAULT_PARKING_PRICES,
  DRIVING_SHARE,
  ELASTICITY_EXPONENT,
  LONG_STAY_AVG_DAYS,
  SHORT_STAY_SHARE,
  type ParkingDemand,
  type ParkingPrices,
  type ParkingSpaces,
} from './data.ts'

export interface OccupancyResult {
  rate: number
  occupied: number
  overflow: number
}

export interface ParkingOccupancyBreakdown extends OccupancyResult {
  short: OccupancyResult
  long: OccupancyResult
}

export interface ParkingRevenueBreakdown {
  short: number
  long: number
  total: number
}

/**
 * Calculates daily parking space-day demand generated by departing passengers
 * for short-stay and long-stay parking, adjusted for price elasticity.
 * Elasticity formula: demand * (defaultPrice / actualPrice) ^ 0.6
 */
export function dailyParkingDemand(
  departingPax: number,
  prices?: Partial<ParkingPrices>
): ParkingDemand {
  const safePax = Math.max(0, departingPax)
  const effectivePrices: ParkingPrices = {
    short: prices?.short ?? DEFAULT_PARKING_PRICES.short,
    long: prices?.long ?? DEFAULT_PARKING_PRICES.long,
  }

  const drivingPax = safePax * DRIVING_SHARE
  const baseShortDemand = drivingPax * SHORT_STAY_SHARE
  const baseLongDemand = drivingPax * (1 - SHORT_STAY_SHARE) * LONG_STAY_AVG_DAYS

  const shortElasticity =
    effectivePrices.short <= 0
      ? 0
      : Math.pow(DEFAULT_PARKING_PRICES.short / effectivePrices.short, ELASTICITY_EXPONENT)

  const longElasticity =
    effectivePrices.long <= 0
      ? 0
      : Math.pow(DEFAULT_PARKING_PRICES.long / effectivePrices.long, ELASTICITY_EXPONENT)

  return {
    short: baseShortDemand * shortElasticity,
    long: baseLongDemand * longElasticity,
  }
}

/**
 * Calculates parking occupancy metrics. Occupancy rate is capped at 1.0 (100%),
 * with any excess demand counted as overflow.
 */
export function occupancy(demand: number, spaces: number): OccupancyResult
export function occupancy(demand: ParkingDemand, spaces: ParkingSpaces): ParkingOccupancyBreakdown
export function occupancy(
  demand: number | ParkingDemand,
  spaces: number | ParkingSpaces
): OccupancyResult | ParkingOccupancyBreakdown
export function occupancy(
  demand: number | ParkingDemand,
  spaces: number | ParkingSpaces
): OccupancyResult | ParkingOccupancyBreakdown {
  if (typeof demand === 'number' && typeof spaces === 'number') {
    const safeDemand = Math.max(0, demand)
    const safeSpaces = Math.max(0, spaces)
    const occupied = Math.min(safeDemand, safeSpaces)
    const overflow = Math.max(0, safeDemand - safeSpaces)
    const rate = safeSpaces > 0 ? Math.min(1, safeDemand / safeSpaces) : 0
    return { rate, occupied, overflow }
  }

  const demandObj = typeof demand === 'number' ? { short: demand, long: demand } : demand
  const spacesObj = typeof spaces === 'number' ? { short: spaces, long: spaces } : spaces

  const shortResult = occupancy(demandObj.short, spacesObj.short)
  const longResult = occupancy(demandObj.long, spacesObj.long)

  const totalDemand = Math.max(0, demandObj.short) + Math.max(0, demandObj.long)
  const totalSpaces = Math.max(0, spacesObj.short) + Math.max(0, spacesObj.long)
  const totalOccupied = shortResult.occupied + longResult.occupied
  const totalOverflow = shortResult.overflow + longResult.overflow
  const rate = totalSpaces > 0 ? Math.min(1, totalDemand / totalSpaces) : 0

  return {
    rate,
    occupied: totalOccupied,
    overflow: totalOverflow,
    short: shortResult,
    long: longResult,
  }
}

/**
 * Calculates daily parking revenue based on occupied spaces and pricing.
 * Any demand exceeding available space is counted as overflow and lost ($0 revenue).
 */
export function dailyRevenue(demand: number, spaces: number, price: number): number
export function dailyRevenue(
  demand: ParkingDemand,
  spaces: ParkingSpaces,
  prices?: Partial<ParkingPrices>
): ParkingRevenueBreakdown
export function dailyRevenue(
  departingPax: number,
  spaces: ParkingSpaces,
  prices?: Partial<ParkingPrices>
): ParkingRevenueBreakdown
export function dailyRevenue(
  demandOrPax: number | ParkingDemand,
  spaces: number | ParkingSpaces,
  pricesOrPrice?: number | Partial<ParkingPrices>
): number | ParkingRevenueBreakdown {
  if (typeof demandOrPax === 'number' && typeof spaces === 'number' && typeof pricesOrPrice === 'number') {
    const safeDemand = Math.max(0, demandOrPax)
    const safeSpaces = Math.max(0, spaces)
    const safePrice = Math.max(0, pricesOrPrice)
    const occupied = Math.min(safeDemand, safeSpaces)
    return occupied * safePrice
  }

  const effectivePrices: ParkingPrices = {
    short:
      typeof pricesOrPrice === 'object' && pricesOrPrice?.short !== undefined
        ? pricesOrPrice.short
        : DEFAULT_PARKING_PRICES.short,
    long:
      typeof pricesOrPrice === 'object' && pricesOrPrice?.long !== undefined
        ? pricesOrPrice.long
        : DEFAULT_PARKING_PRICES.long,
  }

  const spacesObj = typeof spaces === 'object' ? spaces : { short: spaces, long: spaces }

  let demandObj: ParkingDemand
  if (typeof demandOrPax === 'number') {
    demandObj = dailyParkingDemand(demandOrPax, effectivePrices)
  } else {
    demandObj = demandOrPax
  }

  const shortOccupied = Math.min(Math.max(0, demandObj.short), Math.max(0, spacesObj.short))
  const longOccupied = Math.min(Math.max(0, demandObj.long), Math.max(0, spacesObj.long))

  const shortRevenue = shortOccupied * Math.max(0, effectivePrices.short)
  const longRevenue = longOccupied * Math.max(0, effectivePrices.long)

  return {
    short: shortRevenue,
    long: longRevenue,
    total: shortRevenue + longRevenue,
  }
}
